public class Solution {
    public static List<List<Integer>> threeSum(List<Integer> nums) {
        List<List<Integer>> result = new ArrayList<>();
        int n = nums.size();
        List<Integer> numsCopy = new ArrayList<>(nums);

        for (int i = 0; i < n - 2; i++) {
            int target = numsCopy.remove(0);
            List<Integer> curr = new ArrayList<>();
            curr.add(target);
            curr.add(0);
            curr.add(0);
            int index = -1;
            for (int j = 0; j < numsCopy.size(); j++) {
                if (numsCopy.get(j) < curr.get(1)) {
                    index = j;
                    break;
                }
            }
            if (index != -1) {
                curr.set(index, nums.get(i));
                result.add(curr);
            }
        }

        return result;
    }

    public static void main(String[] args) {
        List<Integer> nums = new ArrayList<>();
        nums.add(1);
        nums.add(2);
        nums.add(3);
        nums.add(4);
        nums.add(5);
        List<List<Integer>> result = threeSum(nums);
        for (List<Integer> list : result) {
            for (int num : list) {
                System.out.print(num + " ");
